#include <linux/sched.h>
#include <linux/uaccess.h>
#include <linux/errno.h>

int copy_sched_attr(struct sched_attr __user *uattr, struct sched_attr *attr, unsigned int usize)
{
    int ret;

    if (!access_ok(VERIFY_WRITE, uattr, usize))
        return -EFAULT;

    if (usize < sizeof(struct sched_attr)) {
        if (usize < SCHED_ATTR_SIZE_VER0)
            return -E2BIG;
        ret = copy_from_user(attr, uattr, usize);
        if (ret)
            return -EFAULT;
    } else {
        if (usize > PAGE_SIZE)
            return -E2BIG;
        ret = copy_from_user(attr, uattr, sizeof(struct sched_attr));
        if (ret)
            return -EFAULT;
    }

    if (attr->size > sizeof(struct sched_attr))
        return -E2BIG;

    return 0;
}

int copy_from_user_sched_attr(struct sched_attr __user *uattr, struct sched_attr *attr, unsigned int usize) {
    if (!access_ok(VERIFY_READ, uattr, usize))
        return -EFAULT;

    if (usize < sizeof(*attr)) {
        if (copy_from_user(attr, uattr, usize))
            return -EFAULT;
    } else {
        struct sched_attr tmp;
        if (copy_from_user(&tmp, uattr, sizeof(tmp)))
            return -EFAULT;
        *attr = tmp;
        if (usize > sizeof(*attr)) {
            char zero[offsetof(struct sched_attr, __sizeof_sched_attr) - sizeof(*attr)];
            if (copy_from_user(zero, (char __user *)uattr + sizeof(*attr), sizeof(zero)))
                return -EFAULT;
        }
    }

    return 0;
}

int copy_sched_attr_from_user(struct sched_attr __user *uattr, struct sched_attr *attr, unsigned int usize) {
    int ret;

    if (!access_ok(VERIFY_READ, uattr, usize))
        return -EFAULT;

    if (usize < SCHED_ATTR_SIZE_VER0) {
        if (usize < offsetof(struct sched_attr, size))
            return -EFAULT;
        memset(attr, 0, SCHED_ATTR_SIZE_VER0);
        attr->size = usize;
        ret = copy_from_user(attr, uattr, usize);
        if (ret)
            return -EFAULT;
        return 0;
    }

    if (usize > SCHED_ATTR_SIZE) {
        attr->size = SCHED_ATTR_SIZE;
        if (copy_from_user(attr, uattr, SCHED_ATTR_SIZE)) {
            return -EFAULT;
        }
        return -E2BIG;
    }

    if (copy_from_user(attr, uattr, usize)) {
        return -EFAULT;
    }

    return 0;
}
